import Root from './time-picker.svelte';
import Label from './time-picker-label.svelte';
import InputGroup from './time-picker-input-group.svelte';
import Input from './time-picker-input.svelte';
import Separator from './time-picker-separator.svelte';
import Trigger from './time-picker-trigger.svelte';
import Content from './time-picker-content.svelte';
import Column from './time-picker-column.svelte';
import ColumnItem from './time-picker-column-item.svelte';
import Hour from './time-picker-hour.svelte';
import Minute from './time-picker-minute.svelte';
import Second from './time-picker-second.svelte';
import Period from './time-picker-period.svelte';
import Clear from './time-picker-clear.svelte';

export type {
	TimePickerChildProps,
	TimePickerProps,
	TimePickerRootProps
} from './time-picker.svelte';
export type { TimePickerLabelChildProps, TimePickerLabelProps } from './time-picker-label.svelte';
export type {
	TimePickerInputGroupChildProps,
	TimePickerInputGroupProps
} from './time-picker-input-group.svelte';
export type { TimePickerInputChildProps, TimePickerInputProps } from './time-picker-input.svelte';
export type {
	TimePickerSeparatorChildProps,
	TimePickerSeparatorProps
} from './time-picker-separator.svelte';
export type {
	TimePickerTriggerChildProps,
	TimePickerTriggerProps
} from './time-picker-trigger.svelte';
export type { TimePickerContentProps } from './time-picker-content.svelte';
export type {
	TimePickerColumnChildProps,
	TimePickerColumnProps
} from './time-picker-column.svelte';
export type {
	TimePickerColumnItemChildProps,
	TimePickerColumnItemProps
} from './time-picker-column-item.svelte';
export type { TimePickerHourProps } from './time-picker-hour.svelte';
export type { TimePickerMinuteProps } from './time-picker-minute.svelte';
export type { TimePickerSecondProps } from './time-picker-second.svelte';
export type { TimePickerPeriodProps } from './time-picker-period.svelte';
export type { TimePickerClearChildProps, TimePickerClearProps } from './time-picker-clear.svelte';

export {
	getTimePickerColumnContext,
	getTimePickerContentContext,
	getTimePickerContext,
	getTimePickerInputGroupContext,
	hasTimePickerColumnContext,
	hasTimePickerContentContext,
	hasTimePickerContext,
	hasTimePickerInputGroupContext,
	setTimePickerColumnContext,
	setTimePickerContentContext,
	setTimePickerContext,
	setTimePickerInputGroupContext,
	TimePickerRootState,
	type TimePickerClickAction,
	type TimePickerColumnContext,
	type TimePickerInputGroupContext,
	type TimePickerRootStateProps
} from './time-picker.svelte.js';

// The reuse surfaces this port exports for later components (contracts/time-engine.md).
export {
	ColumnNavigation,
	focusFirstOf,
	type ColumnItemMeta,
	type ColumnMeta,
	type ColumnNavigationProps
} from './column-navigation.svelte.js';

export {
	buildHourValues,
	buildStepValues,
	clamp,
	currentTime,
	DEFAULT_SEGMENT_PLACEHOLDER,
	formatColumnValue,
	formatTimeValue,
	getIs12Hour,
	maxFirstDigit,
	normalizeSegmentPlaceholder,
	parseTimeString,
	PERIODS,
	SEGMENTS,
	stepSegment,
	to12Hour,
	to24Hour,
	togglePeriod,
	// The engine's `Period` type is re-exported as `TimePeriod` here: the barrel already exports a
	// *component* named `Period` (`<TimePicker.Period>`), and one module cannot export the same name
	// twice. `Period` itself stays available from `./time-engine.js`.
	type Period as TimePeriod,
	type ResolvedSegmentPlaceholder,
	type Segment,
	type SegmentFormat,
	type SegmentPlaceholder,
	type TimeValue
} from './time-engine.js';

export {
	Root,
	Label,
	InputGroup,
	Input,
	Separator,
	Trigger,
	Content,
	Column,
	ColumnItem,
	Hour,
	Minute,
	Second,
	Period,
	Clear,
	//
	Root as TimePicker,
	Label as TimePickerLabel,
	InputGroup as TimePickerInputGroup,
	Input as TimePickerInput,
	Separator as TimePickerSeparator,
	Trigger as TimePickerTrigger,
	Content as TimePickerContent,
	Column as TimePickerColumn,
	ColumnItem as TimePickerColumnItem,
	Hour as TimePickerHour,
	Minute as TimePickerMinute,
	Second as TimePickerSecond,
	Period as TimePickerPeriod,
	Clear as TimePickerClear
};

import type { Direction } from '$lib/components/ui/direction-provider/index.js';
import { SegmentNavigation } from '$lib/components/ui/segmented-input/index.js';
import type { DomOrderedCollection } from '$lib/components/ui/speed-dial/speed-dial-collection.svelte.js';
import { getContext, hasContext, setContext } from 'svelte';

import type { ColumnItemMeta, ColumnNavigation } from './column-navigation.svelte.js';
import {
	clamp,
	currentTime,
	formatTimeValue,
	getIs12Hour,
	normalizeSegmentPlaceholder,
	parseTimeString,
	type Period,
	type ResolvedSegmentPlaceholder,
	type Segment,
	type SegmentPlaceholder,
	type TimeValue,
	to12Hour,
	to24Hour
} from './time-engine.js';

/** What a click on empty input-group space does. */
export type TimePickerClickAction = 'focus' | 'open';

export type TimePickerRootStateProps = {
	readonly id: string;
	readonly getValue: () => string;
	readonly setValue: (value: string) => void;
	readonly getOpen: () => boolean;
	readonly setOpen: (open: boolean) => void;
	readonly getDir: () => Direction;
	readonly getLocale: () => string | undefined;
	readonly getSegmentPlaceholder: () => SegmentPlaceholder | undefined;
	readonly getHourStep: () => number;
	readonly getMinuteStep: () => number;
	readonly getSecondStep: () => number;
	readonly getShowSeconds: () => boolean;
	readonly getDisabled: () => boolean;
	readonly getReadOnly: () => boolean;
	readonly getRequired: () => boolean;
	readonly getInvalid: () => boolean;
	readonly getOpenOnFocus: () => boolean;
	readonly getInputGroupClickAction: () => TimePickerClickAction;
	readonly getMin: () => string | undefined;
	readonly getMax: () => string | undefined;
	readonly getName: () => string | undefined;
};

function pad(value: number): string {
	return value.toString().padStart(2, '0');
}

function hasAnyField(value: TimeValue): boolean {
	return (
		value.hour !== undefined ||
		value.minute !== undefined ||
		value.second !== undefined ||
		value.period !== undefined
	);
}

/**
 * One instance per `<TimePicker.Root>`, published on the root context.
 *
 * Replaces upstream's `Store` — `listenersRef` + `stateRef` + `useSyncExternalStore`
 * (radix/ui/time-picker.tsx:196-237, 357-418) — plus its `TimePickerContext` memo. The store exists
 * only so a deep consumer can subscribe to one slice without re-rendering the tree, which runes give
 * for free: a `$derived` read of `root.value` inside `<TimePicker.Hour>` re-runs only that
 * expression (research R-01).
 *
 * Reactive inputs arrive as getter functions rather than snapshots, and both setters keep upstream's
 * `Object.is` guard so `onValueChange` / `onOpenChange` fire exactly as often as upstream's.
 */
export class TimePickerRootState {
	// $derived below is lazy at runtime (evaluated only when the field is read), but svelte-check's
	// static analysis cannot see that and flags the field as used before its constructor assignment.
	#props!: TimePickerRootStateProps;

	/** The root's own id, and the three ids derived from it so they are stable and inspectable. */
	readonly id: string;
	readonly inputGroupId: string;
	readonly labelId: string;
	readonly triggerId: string;

	/** The canonical 24-hour string — `""` when nothing is set. */
	readonly value: string = $derived(this.#props.getValue());

	/** The parsed, partial view of {@link value} that every part reads. */
	readonly timeValue: TimeValue | null = $derived(parseTimeString(this.value));

	readonly open: boolean = $derived(this.#props.getOpen());

	/**
	 * The R-09 latch: set just before `openOnFocus` opens the panel, consumed by the content's
	 * `onOpenAutoFocus` so the caret stays in the segment. Cleared whenever the panel closes.
	 */
	openedViaFocus = $state(false);

	/** The element the popover anchors to, and the boundary the group's click policy tests against. */
	inputGroupElement = $state<HTMLElement | null>(null);

	readonly dir: Direction = $derived(this.#props.getDir());
	readonly is12Hour: boolean = $derived(getIs12Hour(this.#props.getLocale()));
	readonly segmentPlaceholder: ResolvedSegmentPlaceholder = $derived(
		normalizeSegmentPlaceholder(this.#props.getSegmentPlaceholder())
	);
	readonly hourStep: number = $derived(this.#props.getHourStep());
	readonly minuteStep: number = $derived(this.#props.getMinuteStep());
	readonly secondStep: number = $derived(this.#props.getSecondStep());
	readonly showSeconds: boolean = $derived(this.#props.getShowSeconds());
	readonly disabled: boolean = $derived(this.#props.getDisabled());
	readonly readOnly: boolean = $derived(this.#props.getReadOnly());
	readonly required: boolean = $derived(this.#props.getRequired());
	readonly invalid: boolean = $derived(this.#props.getInvalid());
	readonly openOnFocus: boolean = $derived(this.#props.getOpenOnFocus());
	readonly inputGroupClickAction: TimePickerClickAction = $derived(
		this.#props.getInputGroupClickAction()
	);
	readonly name: string | undefined = $derived(this.#props.getName());

	/**
	 * Accepted for upstream parity and reachable from the context, but never enforced: upstream puts
	 * both on its context and never reads them again (research R-23).
	 */
	readonly min: string | undefined = $derived(this.#props.getMin());
	readonly max: string | undefined = $derived(this.#props.getMax());

	/** The segment registry, composed from `segmented-input` rather than re-implemented (R-04). */
	readonly nav: SegmentNavigation;

	constructor(props: TimePickerRootStateProps) {
		this.#props = props;
		this.id = props.id;
		this.inputGroupId = `${props.id}-input-group`;
		this.labelId = `${props.id}-label`;
		this.triggerId = `${props.id}-trigger`;
		this.nav = new SegmentNavigation({
			getOrientation: () => 'horizontal',
			getDir: () => this.dir
		});
	}

	setValue(next: string): void {
		if (Object.is(this.value, next)) return;
		this.#props.setValue(next);
	}

	setOpen(next: boolean): void {
		if (Object.is(this.open, next)) return;
		this.#props.setOpen(next);
		// Upstream clears the latch inside the same `setState` branch (time-picker.tsx:382-384), so it
		// can never survive a close and mis-steer the *next* open.
		if (!next) this.openedViaFocus = false;
	}

	/** Open the panel while latching that focus must stay where it is (R-09). Order matters. */
	openViaFocus(): void {
		if (this.open) return;
		this.openedViaFocus = true;
		this.setOpen(true);
	}

	/** `true` once, when the panel was opened by a segment gaining focus rather than by the trigger. */
	consumeOpenedViaFocus(): boolean {
		if (!this.openedViaFocus) return false;
		this.openedViaFocus = false;
		return true;
	}

	/** Whether `segment` currently holds a value rather than showing its placeholder. */
	hasSegment(segment: Segment): boolean {
		const time = this.timeValue;
		if (!time) return false;
		if (segment === 'period') return time.hour !== undefined;
		return time[segment] !== undefined;
	}

	/**
	 * The committed display text of `segment`, or its placeholder — upstream's `getSegmentValue`
	 * (radix/ui/time-picker.tsx:797-824). The hour is projected through `to12Hour` when the resolved
	 * format is 12-hour; the stored value stays 24-hour either way.
	 */
	segmentText(segment: Segment): string {
		const time = this.timeValue;
		const placeholder = this.segmentPlaceholder[segment];
		if (!time) return placeholder;

		switch (segment) {
			case 'hour': {
				if (time.hour === undefined) return placeholder;
				return pad(this.is12Hour ? to12Hour(time.hour).hour : time.hour);
			}
			case 'minute':
				return time.minute === undefined ? placeholder : pad(time.minute);
			case 'second':
				return time.second === undefined ? placeholder : pad(time.second);
			case 'period':
				return time.hour === undefined ? placeholder : to12Hour(time.hour).period;
		}
	}

	/** The period a new hour should be projected into when the value carries none of its own. */
	#referencePeriod(time: TimeValue | null): Period {
		if (time?.period !== undefined) return time.period;
		if (time?.hour !== undefined) return to12Hour(time.hour).period;
		return to12Hour(currentTime().hour).period;
	}

	/**
	 * Commit one segment's text into the value — upstream's `updateTimeValue`
	 * (radix/ui/time-picker.tsx:837-904), branch for branch.
	 *
	 * `raw` is the **displayed** text, so a 12-hour hour is clamped to `1…12` and projected back to
	 * 24-hour; every other field is clamped to its own range. Text equal to the segment's placeholder
	 * is not a value and is ignored.
	 */
	commitSegment(segment: Segment, raw: string): void {
		if (!raw || raw === this.segmentPlaceholder[segment]) return;

		const time = this.timeValue;
		const next: TimeValue = { ...(time ?? {}) };

		switch (segment) {
			case 'hour': {
				const displayHour = Number.parseInt(raw, 10);
				if (Number.isNaN(displayHour)) break;

				if (this.is12Hour) {
					next.hour = to24Hour(clamp(displayHour, 1, 12), this.#referencePeriod(time));
					if (time?.period !== undefined) next.period = time.period;
				} else {
					next.hour = clamp(displayHour, 0, 23);
				}
				break;
			}
			case 'minute': {
				const minute = Number.parseInt(raw, 10);
				if (!Number.isNaN(minute)) next.minute = clamp(minute, 0, 59);
				break;
			}
			case 'second': {
				const second = Number.parseInt(raw, 10);
				if (!Number.isNaN(second)) next.second = clamp(second, 0, 59);
				break;
			}
			case 'period': {
				if (raw !== 'AM' && raw !== 'PM') break;
				next.period = raw;
				if (time?.hour !== undefined) {
					next.hour = to24Hour(to12Hour(time.hour).hour, raw);
				}
				break;
			}
		}

		this.setValue(formatTimeValue(next, this.showSeconds));
	}

	/** Delete one field, collapsing the whole value to `""` when nothing is left. */
	clearSegment(segment: Segment): void {
		const time = this.timeValue;
		if (!time) {
			this.setValue('');
			return;
		}

		const next: TimeValue = { ...time };
		delete next[segment];

		this.setValue(hasAnyField(next) ? formatTimeValue(next, this.showSeconds) : '');
	}

	/**
	 * Fill the still-unset hour / minute — and second, when `showSeconds` — from the current time,
	 * upstream's blur backfill (radix/ui/time-picker.tsx:932-959). A value that is entirely unset is
	 * left alone: nothing is invented for a field the user never touched.
	 */
	backfillFromNow(): void {
		const time = this.timeValue;
		if (!time) return;

		const now = currentTime();
		const next: TimeValue = { ...time };
		let changed = false;

		if (next.hour === undefined) {
			next.hour = now.hour;
			changed = true;
		}
		if (next.minute === undefined) {
			next.minute = now.minute;
			changed = true;
		}
		if (this.showSeconds && next.second === undefined) {
			next.second = now.second;
			changed = true;
		}

		if (changed) this.setValue(formatTimeValue(next, this.showSeconds));
	}

	/**
	 * Activating an hour column item (radix/ui/time-picker.tsx:1878-1913): set the hour and backfill
	 * the fields that are still unset from now, leaving the panel open.
	 *
	 * `readOnly` suppresses it — upstream's column items commit even while read-only, which
	 * contradicts the flag's documented meaning and lets a mouse user mutate a read-only field
	 * (divergence D-17). The same guard is on every `select*` below.
	 */
	selectHour(displayHour: number): void {
		if (this.disabled || this.readOnly) return;

		const time = this.timeValue;
		const now = currentTime();
		const next: TimeValue = { ...(time ?? {}) };

		next.hour = this.is12Hour ? to24Hour(displayHour, this.#referencePeriod(time)) : displayHour;
		if (time?.period !== undefined) next.period = time.period;
		if (next.minute === undefined) next.minute = now.minute;
		if (this.showSeconds && next.second === undefined) next.second = now.second;

		this.setValue(formatTimeValue(next, this.showSeconds));
	}

	/** Activating a minute column item (radix/ui/time-picker.tsx:1961-1979). */
	selectMinute(minute: number): void {
		if (this.disabled || this.readOnly) return;

		const now = currentTime();
		const next: TimeValue = { ...(this.timeValue ?? {}), minute };

		if (next.hour === undefined) next.hour = now.hour;
		if (this.showSeconds && next.second === undefined) next.second = now.second;

		this.setValue(formatTimeValue(next, this.showSeconds));
	}

	/**
	 * Activating a second column item (radix/ui/time-picker.tsx:2026-2044). Upstream serialises with
	 * seconds unconditionally here — composing the column *is* the request for that arity — so the
	 * `showSeconds` flag is deliberately not consulted.
	 */
	selectSecond(second: number): void {
		if (this.disabled || this.readOnly) return;

		const now = currentTime();
		const next: TimeValue = { ...(this.timeValue ?? {}), second };

		if (next.hour === undefined) next.hour = now.hour;
		if (next.minute === undefined) next.minute = now.minute;

		this.setValue(formatTimeValue(next, true));
	}

	/** Activating a period column item (radix/ui/time-picker.tsx:2082-2106). */
	selectPeriod(period: Period): void {
		if (this.disabled || this.readOnly) return;

		const time = this.timeValue;
		const now = currentTime();
		const next: TimeValue = { ...(time ?? {}) };

		next.hour = to24Hour(to12Hour(time?.hour ?? now.hour).hour, period);
		if (next.minute === undefined) next.minute = now.minute;
		if (this.showSeconds && next.second === undefined) next.second = now.second;

		this.setValue(formatTimeValue(next, this.showSeconds));
	}

	/** Reset to `""`. No-op while `disabled` or `readOnly`. */
	clear(): void {
		if (this.disabled || this.readOnly) return;
		this.setValue('');
	}

	/**
	 * Focus and fully select the first registered segment — what a click on empty group space does
	 * under the default `inputGroupClickAction="focus"` (radix/ui/time-picker.tsx:672-687).
	 */
	focusFirstSegment(): void {
		this.nav.focusAt(0, 'all');
	}
}

// ---------------------------------------------------------------------------
// Contexts — four Symbol keys, four throwing getters
// ---------------------------------------------------------------------------

const TIME_PICKER_CONTEXT_KEY = Symbol('time-picker');

export function setTimePickerContext(state: TimePickerRootState): TimePickerRootState {
	return setContext(TIME_PICKER_CONTEXT_KEY, state);
}

export function hasTimePickerContext(): boolean {
	return hasContext(TIME_PICKER_CONTEXT_KEY);
}

/** Read the picker's state, throwing when there is no `<TimePicker.Root>` ancestor. */
export function getTimePickerContext(consumerName = '<TimePicker.Part>'): TimePickerRootState {
	if (!hasTimePickerContext()) {
		throw new Error(`\`${consumerName}\` must be used within \`<TimePicker.Root>\`.`);
	}
	return getContext<TimePickerRootState>(TIME_PICKER_CONTEXT_KEY);
}

/** What `<TimePicker.InputGroup>` publishes for its segment inputs. */
export type TimePickerInputGroupContext = {
	/** The group's rendered element — the popover anchor and the click-target boundary. */
	readonly getElement: () => HTMLElement | null;
};

const TIME_PICKER_INPUT_GROUP_CONTEXT_KEY = Symbol('time-picker-input-group');

export function setTimePickerInputGroupContext(
	context: TimePickerInputGroupContext
): TimePickerInputGroupContext {
	return setContext(TIME_PICKER_INPUT_GROUP_CONTEXT_KEY, context);
}

export function hasTimePickerInputGroupContext(): boolean {
	return hasContext(TIME_PICKER_INPUT_GROUP_CONTEXT_KEY);
}

/** Read the group's context, throwing when there is no `<TimePicker.InputGroup>` ancestor. */
export function getTimePickerInputGroupContext(
	consumerName = '<TimePicker.Input>'
): TimePickerInputGroupContext {
	if (!hasTimePickerInputGroupContext()) {
		throw new Error(`\`${consumerName}\` must be used within \`<TimePicker.InputGroup>\`.`);
	}
	return getContext<TimePickerInputGroupContext>(TIME_PICKER_INPUT_GROUP_CONTEXT_KEY);
}

const TIME_PICKER_CONTENT_CONTEXT_KEY = Symbol('time-picker-content');

export function setTimePickerContentContext(nav: ColumnNavigation): ColumnNavigation {
	return setContext(TIME_PICKER_CONTENT_CONTEXT_KEY, nav);
}

export function hasTimePickerContentContext(): boolean {
	return hasContext(TIME_PICKER_CONTENT_CONTEXT_KEY);
}

/** Read the panel's column navigation, throwing when there is no `<TimePicker.Content>` ancestor. */
export function getTimePickerContentContext(
	consumerName = '<TimePicker.Column>'
): ColumnNavigation {
	if (!hasTimePickerContentContext()) {
		throw new Error(`\`${consumerName}\` must be used within \`<TimePicker.Content>\`.`);
	}
	return getContext<ColumnNavigation>(TIME_PICKER_CONTENT_CONTEXT_KEY);
}

/** What `<TimePicker.Column>` publishes for its items. */
export type TimePickerColumnContext = {
	/** The column's own id, as registered with the panel's {@link ColumnNavigation}. */
	readonly id: string;
	/** The column's own item registry, which every item self-registers with. */
	readonly items: DomOrderedCollection<ColumnItemMeta>;
};

const TIME_PICKER_COLUMN_CONTEXT_KEY = Symbol('time-picker-column');

export function setTimePickerColumnContext(
	context: TimePickerColumnContext
): TimePickerColumnContext {
	return setContext(TIME_PICKER_COLUMN_CONTEXT_KEY, context);
}

export function hasTimePickerColumnContext(): boolean {
	return hasContext(TIME_PICKER_COLUMN_CONTEXT_KEY);
}

/** Read the column's context, throwing when there is no `<TimePicker.Column>` ancestor. */
export function getTimePickerColumnContext(
	consumerName = '<TimePicker.ColumnItem>'
): TimePickerColumnContext {
	if (!hasTimePickerColumnContext()) {
		throw new Error(`\`${consumerName}\` must be used within \`<TimePicker.Column>\`.`);
	}
	return getContext<TimePickerColumnContext>(TIME_PICKER_COLUMN_CONTEXT_KEY);
}

import type { Direction } from '$lib/components/ui/direction-provider/index.js';
import { resolveSegmentIntent } from '$lib/components/ui/segmented-input/index.js';
import {
	DomOrderedCollection,
	type DomOrderedEntry
} from '$lib/components/ui/speed-dial/speed-dial-collection.svelte.js';

/** What every column item publishes at registration time, read live so it is never stale. */
export type ColumnItemMeta = {
	readonly value: number | string;
	readonly getSelected: () => boolean;
};

/** What every column publishes at registration time. */
export type ColumnMeta = {
	readonly getItems: () => readonly DomOrderedEntry<ColumnItemMeta>[];
};

/**
 * Focus the first candidate that actually takes focus, in preference order
 * (radix/ui/time-picker.tsx:79-91).
 *
 * A candidate that already has focus ends the walk — re-focusing it would be a no-op that hides a
 * later, focusable candidate — and so does the first one that succeeds. Nothing focusable leaves the
 * active element exactly where it was.
 */
export function focusFirstOf(elements: readonly HTMLElement[]): void {
	const previous = document.activeElement;

	for (const element of elements) {
		if (element === previous) return;
		element.focus({ preventScroll: false });
		if (document.activeElement !== previous) return;
	}
}

function wrap(index: number, length: number, step: 1 | -1): number {
	if (length === 0) return -1;
	if (step === 1) return index < length - 1 ? index + 1 : 0;
	return index > 0 ? index - 1 : length - 1;
}

export type ColumnNavigationProps = {
	readonly getDir: () => Direction;
};

/**
 * The wrap-around focus model of a multi-column roulette picker: several independent,
 * simultaneously-visible columns, each committing its own value while the panel stays open.
 *
 * Written once here and **exported for reuse** — a Date Picker's day/month/year columns or a
 * Duration Picker need exactly this and nothing more. bits-ui's `Select` / `Listbox` / `Menu` were
 * evaluated and rejected: all of them close on selection, own their own value and model a single
 * list (research R-14). The document-ordered registry underneath is `DomOrderedCollection`, composed
 * rather than rewritten, and the RTL key mapping is `segmented-input`'s `resolveSegmentIntent`.
 *
 * Ordering is document order throughout: upstream's per-keystroke numeric sort is provably a no-op
 * for every column it generates, and document order is additionally correct for a caller who
 * composes `<TimePicker.Column>` with their own item set (research R-15).
 *
 * ```ts
 * const nav = new ColumnNavigation({ getDir: () => root.dir });
 * ```
 */
export class ColumnNavigation {
	// $derived below is lazy at runtime (evaluated only when the field is read), but svelte-check's
	// static analysis cannot see that and flags the field as used before its constructor assignment.
	#props!: ColumnNavigationProps;

	/** Every registered column, in document order. */
	readonly columns = new DomOrderedCollection<ColumnMeta>();

	/** How many columns are currently registered and attached. */
	readonly count: number = $derived(this.columns.size);

	constructor(props: ColumnNavigationProps) {
		this.#props = props;
	}

	/** Idempotent — re-registering the same id replaces the entry. */
	registerColumn(id: string, element: HTMLElement, meta: ColumnMeta): void {
		this.columns.register(id, element, meta);
	}

	/** No-op for an unknown id. */
	unregisterColumn(id: string): void {
		this.columns.unregister(id);
	}

	/** `-1` while the column is unregistered. */
	indexOfColumn(id: string): number {
		return this.columns.indexById.get(id) ?? -1;
	}

	/** Which registered column contains `element`, or `-1`. */
	columnIndexOf(element: Element | null): number {
		if (!element) return -1;
		return this.columns.ordered.findIndex((column) => column.element.contains(element));
	}

	/**
	 * Focus the column's selected item, falling back to its first focusable one — upstream's
	 * `focusFirst(selected ? [selected, ...items] : items)` (radix/ui/time-picker.tsx:1556-1563).
	 */
	focusPreferredIn(columnIndex: number): void {
		const column = this.columns.ordered[columnIndex];
		if (!column) return;

		const items = column.meta.getItems();
		if (items.length === 0) return;

		const selected = items.find((item) => item.meta.getSelected());
		const elements = items.map((item) => item.element);

		focusFirstOf(selected ? [selected.element, ...elements] : elements);
	}

	/**
	 * Previous/next item in the same column, **wrapping** at both ends. The target is focused *and*
	 * clicked: arrowing through a column selects as it moves, which is upstream behaviour rather than
	 * an accident (radix/ui/time-picker.tsx:1777-1779).
	 */
	moveWithinColumn(columnId: string, itemId: string, step: 1 | -1): void {
		const column = this.columns.ordered[this.indexOfColumn(columnId)];
		if (!column) return;

		const items = column.meta.getItems();
		const current = items.findIndex((item) => item.id === itemId);
		if (current === -1) return;

		const target = items[wrap(current, items.length, step)];
		if (!target) return;

		target.element.focus();
		target.element.click();
	}

	/** Previous/next column, **wrapping**, landing on that column's selected item else its first. */
	moveAcrossColumns(fromColumnId: string, step: 1 | -1): void {
		const current = this.indexOfColumn(fromColumnId);
		if (current === -1) return;

		const target = wrap(current, this.columns.ordered.length, step);
		if (target === -1) return;

		this.focusPreferredIn(target);
	}

	/**
	 * The column items' whole keyboard contract.
	 *
	 * `ArrowUp`/`ArrowDown` walk the column; `ArrowLeft`/`ArrowRight` walk the columns through
	 * `resolveSegmentIntent`, so they invert under `dir="rtl"` (research R-16); `Tab`/`Shift+Tab` walk
	 * the columns direction-independently, matching every other tab order. Only the keys it handles
	 * are `preventDefault()`ed, and a caller handler that already prevented the event vetoes all of
	 * it.
	 */
	onItemKeydown(event: KeyboardEvent, columnId: string, itemId: string): void {
		if (event.defaultPrevented) return;

		if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
			event.preventDefault();
			this.moveWithinColumn(columnId, itemId, event.key === 'ArrowDown' ? 1 : -1);
			return;
		}

		if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
			const intent = resolveSegmentIntent(event.key, 'horizontal', this.#props.getDir());
			if (intent !== 'next' && intent !== 'previous') return;

			event.preventDefault();
			this.moveAcrossColumns(columnId, intent === 'next' ? 1 : -1);
			return;
		}

		if (event.key === 'Tab') {
			event.preventDefault();
			this.moveAcrossColumns(columnId, event.shiftKey ? -1 : 1);
		}
	}
}

/**
 * The Time Picker's pure value logic: parsing, formatting, 12↔24 conversion, wrap-around stepping,
 * locale format detection and column value generation.
 *
 * Rune-free, Svelte-free and DOM-free by design, so it is SSR-safe, directly unit-testable and
 * reusable — a Date Picker, a Duration Input or a Calendar time field would otherwise re-derive all
 * of it. The same reasoning that made `mask-input` export `mask-engine.ts` and `phone-input` export
 * `phone-engine.ts` (research R-02, contracts/time-engine.md §A).
 *
 * Every function is **total**: it never throws, and every documented input maps to a documented
 * output.
 */

/**
 * Every editable segment, in **auto-advance order** — the declaration order is significant, because
 * digit entry walks it to find the next segment (radix/ui/time-picker.tsx:612).
 */
export const SEGMENTS = ['hour', 'minute', 'second', 'period'] as const;

/** The two periods of a 12-hour clock, in upstream declaration order. */
export const PERIODS = ['AM', 'PM'] as const;

/** What an unset segment displays, and what `formatTimeValue` writes for a missing field. */
export const DEFAULT_SEGMENT_PLACEHOLDER = '--';

/** `'hour' | 'minute' | 'second' | 'period'`. */
export type Segment = (typeof SEGMENTS)[number];

/** `'AM' | 'PM'`. */
export type Period = (typeof PERIODS)[number];

/**
 * How a dropdown column renders its items: `'2-digit'` zero-pads a numeric value, `'numeric'` prints
 * it bare. Non-numeric values (the periods) always print bare.
 */
export type SegmentFormat = 'numeric' | '2-digit';

/**
 * The **partial**, in-flight time. Every field is independently optional, which is what makes a
 * half-entered `"10:--"` expressible.
 *
 * `hour` is **always** 24-hour, whatever the display format; `period` is its display-only companion
 * and is never serialised.
 */
export type TimeValue = {
	hour?: number;
	minute?: number;
	second?: number;
	period?: Period;
};

/** A single placeholder for every segment, or one per segment. */
export type SegmentPlaceholder =
	| string
	| {
			hour?: string;
			minute?: string;
			second?: string;
			period?: string;
	  };

/** {@link SegmentPlaceholder} widened so every segment has a string. */
export type ResolvedSegmentPlaceholder = Record<Segment, string>;

/**
 * Whether `locale` displays a 12-hour clock, decided by asking `Intl` to format 13:00
 * (radix/ui/time-picker.tsx:111-118) — never by consulting a hard-coded locale table.
 *
 * The second clause catches locales that render a 12-hour clock without a Latin `AM`/`PM` marker
 * (`ja-JP` renders `午後1時`). An invalid locale tag makes `Intl.DateTimeFormat` throw, which is
 * caught here and answered with the runtime default so the function stays total.
 */
export function getIs12Hour(locale?: string): boolean {
	const testDate = new Date(2000, 0, 1, 13, 0, 0);

	let formatted: string;
	try {
		formatted = new Intl.DateTimeFormat(locale, { hour: 'numeric' }).format(testDate);
	} catch {
		formatted = new Intl.DateTimeFormat(undefined, { hour: 'numeric' }).format(testDate);
	}

	return /am|pm/i.test(formatted) || !formatted.includes('13');
}

/** One `:`-separated part, or `undefined` when it is absent, the placeholder, or out of range. */
function parsePart(part: string | undefined, max: number): number | undefined {
	if (!part || part === DEFAULT_SEGMENT_PLACEHOLDER) return undefined;
	const parsed = Number.parseInt(part, 10);
	if (Number.isNaN(parsed) || parsed < 0 || parsed > max) return undefined;
	return parsed;
}

/**
 * The inverse of {@link formatTimeValue}, and total (radix/ui/time-picker.tsx:120-157).
 *
 * Returns `null` for an empty string, for a string with fewer than two `:`-separated parts, and for
 * one whose every part is absent or out of range. An individual `"--"` or out-of-range part is
 * dropped rather than failing the whole parse, which is what keeps `"10:--"` a usable value.
 */
export function parseTimeString(timeString: string | undefined): TimeValue | null {
	if (!timeString) return null;

	const parts = timeString.split(':');
	if (parts.length < 2) return null;

	const result: TimeValue = {};

	const hour = parsePart(parts[0], 23);
	if (hour !== undefined) result.hour = hour;

	const minute = parsePart(parts[1], 59);
	if (minute !== undefined) result.minute = minute;

	const second = parsePart(parts[2], 59);
	if (second !== undefined) result.second = second;

	if (result.hour === undefined && result.minute === undefined && result.second === undefined) {
		return null;
	}

	return result;
}

function pad(value: number): string {
	return value.toString().padStart(2, '0');
}

/**
 * Serialise to the canonical 24-hour string — `"HH:mm"`, or `"HH:mm:ss"` when `showSeconds`.
 *
 * Each unset field renders `"--"`, and `period` is never serialised: the stored `hour` already
 * carries it.
 */
export function formatTimeValue(value: TimeValue, showSeconds: boolean): string {
	const hour = value.hour !== undefined ? pad(value.hour) : DEFAULT_SEGMENT_PLACEHOLDER;
	const minute = value.minute !== undefined ? pad(value.minute) : DEFAULT_SEGMENT_PLACEHOLDER;

	if (!showSeconds) return `${hour}:${minute}`;

	const second = value.second !== undefined ? pad(value.second) : DEFAULT_SEGMENT_PLACEHOLDER;
	return `${hour}:${minute}:${second}`;
}

/**
 * The ambient clock, as the three fields the backfill and the column pre-highlighting need.
 *
 * The one deliberately impure function in this module, and the only place the component reads the
 * clock — upstream calls `new Date()` in nine separate handlers. Keeping it here means the reads stay
 * out of the runes modules (`svelte/prefer-svelte-reactivity` rightly rejects a mutable `Date` in a
 * `.svelte.ts` file) and that a test can pin every one of them with a single `vi.setSystemTime`.
 */
export function currentTime(): { hour: number; minute: number; second: number } {
	const now = new Date();
	return { hour: now.getHours(), minute: now.getMinutes(), second: now.getSeconds() };
}

/** Split a 24-hour hour into what a 12-hour clock displays plus its period. */
export function to12Hour(hour24: number): { hour: number; period: Period } {
	return { hour: hour24 % 12 || 12, period: hour24 >= 12 ? 'PM' : 'AM' };
}

/** The inverse of {@link to12Hour}: `12` is the special case that maps to `00` in the morning. */
export function to24Hour(hour12: number, period: Period): number {
	if (hour12 === 12) return period === 'PM' ? 12 : 0;
	return period === 'PM' ? hour12 + 12 : hour12;
}

/** `Math.min(Math.max(value, min), max)`. */
export function clamp(value: number, min: number, max: number): number {
	return Math.min(Math.max(value, min), max);
}

/**
 * Widen a caller's `segmentPlaceholder` to one string per segment
 * (radix/ui/time-picker.tsx:422-437). A bare string fills all four; an object fills only the keys it
 * names and leaves the rest at `"--"`; `undefined` yields all `"--"`.
 */
export function normalizeSegmentPlaceholder(
	input: SegmentPlaceholder | undefined
): ResolvedSegmentPlaceholder {
	if (input === undefined) {
		return {
			hour: DEFAULT_SEGMENT_PLACEHOLDER,
			minute: DEFAULT_SEGMENT_PLACEHOLDER,
			second: DEFAULT_SEGMENT_PLACEHOLDER,
			period: DEFAULT_SEGMENT_PLACEHOLDER
		};
	}

	if (typeof input === 'string') {
		return { hour: input, minute: input, second: input, period: input };
	}

	return {
		hour: input.hour ?? DEFAULT_SEGMENT_PLACEHOLDER,
		minute: input.minute ?? DEFAULT_SEGMENT_PLACEHOLDER,
		second: input.second ?? DEFAULT_SEGMENT_PLACEHOLDER,
		period: input.period ?? DEFAULT_SEGMENT_PLACEHOLDER
	};
}

/**
 * One `ArrowUp` / `ArrowDown` step, **with wrap-around at every boundary**
 * (radix/ui/time-picker.tsx:1303-1385):
 *
 * | Segment | Format | up at max | down at min | empty + up | empty + down |
 * | ------- | ------ | --------- | ----------- | ---------- | ------------ |
 * | hour    | 24h    | `23 → 0`  | `0 → 23`    | `0`        | `23`         |
 * | hour    | 12h    | `12 → 1`  | `1 → 12`    | `12`       | `12`         |
 * | minute  | —      | `59 → 0`  | `0 → 59`    | `0`        | `59`         |
 * | second  | —      | `59 → 0`  | `0 → 59`    | `0`        | `59`         |
 *
 * `current` is the **displayed** number, so a 12-hour hour steps through `1…12` rather than `0…23`.
 * The `period` segment is never stepped here — it toggles through {@link togglePeriod} — so it is
 * answered with `current ?? 0` to keep the function total.
 */
export function stepSegment(
	segment: Segment,
	current: number | null,
	delta: 1 | -1,
	is12Hour: boolean
): number {
	if (segment === 'period') return current ?? 0;

	if (current === null) {
		if (segment === 'hour') {
			if (is12Hour) return 12;
			return delta === 1 ? 0 : 23;
		}
		return delta === 1 ? 0 : 59;
	}

	if (segment === 'hour') {
		if (is12Hour) {
			if (delta === 1) return current === 12 ? 1 : current + 1;
			return current === 1 ? 12 : current - 1;
		}
		if (delta === 1) return current === 23 ? 0 : current + 1;
		return current === 0 ? 23 : current - 1;
	}

	if (delta === 1) return current === 59 ? 0 : current + 1;
	return current === 0 ? 59 : current - 1;
}

/**
 * The period segment's strict two-state toggle (radix/ui/time-picker.tsx:1245-1248). An unset period
 * counts as `AM`, so the first press always lands on `PM`; there is no third state.
 */
export function togglePeriod(current: Period | null): Period {
	return current === 'PM' ? 'AM' : 'PM';
}

/**
 * The hour column's values (radix/ui/time-picker.tsx:1865-1876). 12-hour clocks list
 * `12, 1, 2, …` — a rotation of `1…12` — and 24-hour clocks list `0, step, 2·step, …`.
 * A non-positive step yields `[]` rather than looping forever.
 */
export function buildHourValues(is12Hour: boolean, hourStep: number): number[] {
	if (!Number.isFinite(hourStep) || hourStep <= 0) return [];

	const limit = is12Hour ? 12 : 24;
	return Array.from({ length: Math.ceil(limit / hourStep) }, (_, index) => {
		const value = index * hourStep;
		if (!is12Hour) return value;
		return value % 12 || 12;
	});
}

/**
 * The minute and second columns' values: `⌈limit / step⌉` entries of `i · step`. A non-positive step
 * yields `[]`.
 */
export function buildStepValues(limit: number, step: number): number[] {
	if (!Number.isFinite(step) || step <= 0) return [];
	return Array.from({ length: Math.ceil(limit / step) }, (_, index) => index * step);
}

/** A column item's rendered text: `'2-digit'` zero-pads a number, everything else prints bare. */
export function formatColumnValue(value: number | string, format: SegmentFormat): string {
	if (format === '2-digit' && typeof value === 'number') return pad(value);
	return String(value);
}

/**
 * The largest first digit that can still be followed by a second one
 * (radix/ui/time-picker.tsx:1049). Typing anything greater commits the segment and advances
 * immediately, which is what makes a bare `9` mean `09` in a 24-hour hour.
 *
 * `period` returns `-1`: it never auto-advances by digit, it takes the `A`/`P`/`1`/`2` shortcuts.
 */
export function maxFirstDigit(segment: Segment, is12Hour: boolean): number {
	if (segment === 'hour') return is12Hour ? 1 : 2;
	if (segment === 'period') return -1;
	return 5;
}
